const visual = {
  prepare: function (input) { return [{ kind: 'text', payload: '1:1' }]; },
  render: function (input, metrics) {
    var W = input.viewport.widthDu, H = input.viewport.heightDu;
    var y = H * 0.60, x0 = 40, x1 = W - 40, xm = (x0 + x1) / 2;
    var bar = [['M', x0, y], ['L', xm, y], ['M', xm, y], ['L', x1, y]];
    return {
      schemaVersion: 1,
      sceneId: 'fixture-ratio-1to1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'bar', commands: bar }],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'bar', fill: '#333333', stroke: { width: 4, cap: 'butt', join: 'miter', miterLimit: 4, dash: null } },
        { type: 'label', contentId: metrics[0].contentId,
          anchor: { x: xm, y: y - 18 }, hAlign: 'center', vAlign: 'bottom',
          color: '#333333' }
      ] }
    };
  }
};
